<?php
declare(strict_types=1);require_once __DIR__.'/includes/layout.php';login_required();$pdo=db();$type=(string)($_GET['type']??'revenue');$rows=[];$title='';
switch($type){
case 'reservations':$title='Reservations';$rows=$pdo->query("SELECT CONCAT(c.customer_firstname,' ',c.customer_lastname) customer,r.room_id,r.checkin_date,r.checkout_date,r.reservation_price,r.status FROM reservation r JOIN customer c ON c.customer_id=r.customer_id ORDER BY r.checkin_date DESC")->fetchAll();break;
case 'services':$title='Service Usage';$rows=$pdo->query("SELECT 'Restaurant' service,COUNT(*) count,COALESCE(SUM(book_price),0) total FROM restaurant_booking UNION ALL SELECT 'Sport',COUNT(*),COALESCE(SUM(dosport_price),0) FROM do_sport UNION ALL SELECT 'Medical',COUNT(*),COALESCE(SUM(medicalservice_price),0) FROM get_medicalservice UNION ALL SELECT 'Massage',COUNT(*),COALESCE(SUM(massage_price),0) FROM massage_service UNION ALL SELECT 'Room Service',COUNT(*),COALESCE(SUM(roomservice_price),0) FROM get_roomservice UNION ALL SELECT 'Laundry',COUNT(*),COALESCE(SUM(laundry_price),0) FROM laundry_service")->fetchAll();break;
case 'guests':$title='Current Guests';$rows=$pdo->query("SELECT CONCAT(c.customer_firstname,' ',c.customer_lastname) customer,rs.room_id,rs.checkin_date,rs.checkout_date,rs.room_sales_price,rs.total_service_price FROM room_sales rs JOIN customer c ON c.customer_id=rs.customer_id WHERE rs.checkin_date<=CURDATE() AND rs.checkout_date>=CURDATE() ORDER BY rs.checkin_date")->fetchAll();break;
default:$title='Customer Revenue';$rows=$pdo->query("SELECT CONCAT(c.customer_firstname,' ',c.customer_lastname) customer,COUNT(*) checkins,COALESCE(SUM(rs.room_sales_price+rs.total_service_price),0) total_paid FROM room_sales rs JOIN customer c ON c.customer_id=rs.customer_id GROUP BY rs.customer_id ORDER BY total_paid DESC")->fetchAll();
}
page_header($title,'reports');?>
<div class="page-head"><div><h1><?=$title?></h1><p class="muted">Operational reports</p></div><button class="btn" onclick="window.print()">Print</button></div><div class="report-tabs"><a href="reports.php?type=revenue">Revenue</a><a href="reports.php?type=reservations">Reservations</a><a href="reports.php?type=guests">Current Guests</a><a href="reports.php?type=services">Services</a></div>
<section class="card table-wrap"><table><thead><tr><?php if($type==='services'):?><th>Service</th><th>Count</th><th>Total</th><?php elseif($type==='revenue'):?><th>Customer</th><th>Check-ins</th><th>Total Paid</th><?php else:?><th>Customer</th><th>Room</th><th>Check-in</th><th>Check-out</th><th>Amount</th><?php endif;?></tr></thead><tbody><?php foreach($rows as $r):?><tr><?php if($type==='services'):?><td><?=e($r['service'])?></td><td><?=$r['count']?></td><td><?=money($r['total'])?></td><?php elseif($type==='revenue'):?><td><?=e($r['customer'])?></td><td><?=$r['checkins']?></td><td><?=money($r['total_paid'])?></td><?php else:?><td><?=e($r['customer'])?></td><td><?=$r['room_id']?></td><td><?=$r['checkin_date']?></td><td><?=$r['checkout_date']?></td><td><?=money((float)($r['reservation_price']??0)+(float)($r['room_sales_price']??0)+(float)($r['total_service_price']??0))?></td><?php endif;?></tr><?php endforeach;?></tbody></table></section><?php page_footer();?>
